mapper.select:
SELECT c.challenge_id AS challengeId, c.title, c.description, c.type, c.target_value AS targetValue, c.start_date AS startDate, c.end_date AS endDate, c.goal_count AS goalCount, c.max_participants AS maxParticipants, (SELECT COUNT(*) FROM user_challenges uc WHERE uc.challenge_id = c.challenge_id) as currentHeadCount,
-- LEFT JOIN된 uc.user_challenge_id가 존재하면 1(true), 아니면 0(false) CASE WHEN uc.user_challenge_id IS NOT NULL THEN 1 ELSE 0 END AS isJoined,
-- 내 진행 상황 (참여 안 했으면 0/null 반환) uc.status, IFNULL(uc.current_count, 0) AS currentCount, IFNULL(uc.current_streak, 0) AS currentStreak FROM challenges c -- 유저 ID를 조건으로 LEFT JOIN 추가 LEFT JOIN user_challenges uc ON c.challenge_id = uc.challenge_id AND uc.user_id = #{userId}
WHERE c.is_public = true
AND c.type = #{cond.type}
AND c.start_date >= #{cond.startDate}
AND c.end_date <= #{cond.endDate}
AND c.title LIKE CONCAT('%', #{cond.keyword}, '%')
ORDER BY c.start_date DESC

SELECT COUNT(*) > 0
FROM user_challenges
WHERE user_id = #{userId}
  AND challenge_id = #{challengeId}
  AND status = 'PROGRESS'

SELECT COUNT(*) > 0
FROM challenge_invitations
WHERE challenge_id = #{challengeId}
AND invitee_id = #{inviteeId}
AND status = 'PENDING'

mapper.update:
UPDATE challenges
SET current_head_count = current_head_count + 1
WHERE challenge_id = #{challengeId}

UPDATE challenges
SET current_head_count = current_head_count - 1
WHERE challenge_id = #{challengeId}

UPDATE invitations
SET status = #{status}
WHERE invitation_id = #{invitationId}

mapper.select:
SELECT i.invitation_id AS invitationId, i.created_at AS sentAt,
/* 보낸 사람 정보 */ u.user_id AS inviterId, u.user_name AS inviterName, u.profile_image AS inviterProfileImage,
/* 챌린지 정보 */ c.challenge_id AS challengeId, c.title AS challengeTitle, c.type AS type, c.target_value AS targetValue, c.goal_count AS goalCount, c.current_head_count AS currentHeadCount, c.max_participants AS maxParticipants
FROM invitations i JOIN users u ON i.inviter_id = u.user_id JOIN challenges c ON i.challenge_id = c.challenge_id
WHERE i.invitee_id = #{userId} AND i.status = 'PENDING' ORDER BY i.created_at DESC
